from test.support import import_helper, threading_helper
syslog = import_helper.import_module('syslog')

def _t():
    mask = syslog.LOG_UPTO(syslog.LOG_WARNING)
    assert mask & syslog.LOG_MASK(syslog.LOG_WARNING), ('assertTrue', mask & syslog.LOG_MASK(syslog.LOG_WARNING))
    assert mask & syslog.LOG_MASK(syslog.LOG_ERR), ('assertTrue', mask & syslog.LOG_MASK(syslog.LOG_ERR))
    assert not mask & syslog.LOG_MASK(syslog.LOG_INFO), ('assertFalse', mask & syslog.LOG_MASK(syslog.LOG_INFO))
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

